/* ---------- styles (theme tokens; the default look is the reference) */
const css=`
.wk3{color:var(--wk-text);background:var(--wk-bg);min-height:100%;margin:0 calc(50% - 50vw);padding:0 16px calc(104px + env(safe-area-inset-bottom,0px));direction:var(--wk-dir,rtl);font-size:15px}
.wk3 *{box-sizing:border-box}
.wk3 button{font:inherit;color:inherit;-webkit-tap-highlight-color:transparent;border:0;background:none;margin:0;padding:0;min-width:0;min-height:0;box-shadow:none;cursor:pointer;text-align:inherit}
.wk3 .mi{display:block;width:100%;height:100%;object-fit:contain;pointer-events:none;user-select:none}
.wk3 .mi.white{filter:saturate(0) brightness(1.6)}
html[data-wkt=free_light] .wk3 .mi.white{filter:none}
html[data-wkt=free_light] .wk3 svg.mi{stroke:#1F5EFF}
html[data-wkt=free_light] .m3-name .v .mi{filter:hue-rotate(-42deg) saturate(1.3)}
html[data-wkt=free_light] .m3-vip{background:#14181F;border-radius:999px}
/* top row: settings (left) · photo (centre) · edit (right) — same on every language, like the picture */
/* profile background (only on the profile, never the app theme): wide picture behind the top, fading into the page */
.wk3{position:relative;isolation:isolate}
.m3-cover{position:absolute;left:0;right:0;top:0;height:calc(min(75vw,420px) + var(--wk-st,0px));z-index:-1;overflow:hidden;pointer-events:none;-webkit-mask-image:linear-gradient(#000 52%,transparent);mask-image:linear-gradient(#000 52%,transparent)}
.m3-cover img{width:100%;height:100%;object-fit:cover;display:block}
.m3-cover i{position:absolute;inset:0;background:#000}
.wk3.has-bg .m3-name,.wk3.has-bg .m3-name span,.wk3.has-bg .m3-user{color:#fff!important;text-shadow:0 1px 10px rgba(0,0,0,.7),0 0 2px rgba(0,0,0,.5)}
.wk3.has-bg .m3-user{opacity:.92}
.m3-top{position:relative;height:calc(150px + var(--wk-st,0px));padding-top:calc(14px + var(--wk-st,0px));direction:ltr}
.m3-sq{position:absolute;top:calc(14px + var(--wk-st,0px));width:44px;height:44px;border-radius:12px!important;border:1px solid color-mix(in srgb,var(--wk-text) 24%,transparent)!important;background:color-mix(in srgb,var(--wk-surface) 70%,transparent)!important;padding:10px!important}
.m3-sq.l{left:0}.m3-sq.r{right:0}
.m3-av{position:absolute;left:50%;top:calc(10px + var(--wk-st,0px));width:132px;height:132px;transform:translateX(-50%);border-radius:50%;padding:3px;background:linear-gradient(160deg,#D9C6FF,#9B6BFF 55%,#7C4DDB)}
html[data-wkt]:not([data-wkt=vip_purple]):not([data-wkt=free_dark]) .m3-av{background:linear-gradient(160deg,color-mix(in srgb,var(--wk-accent) 60%,#fff),var(--wk-accent))}
.m3-av.fr{background:none!important}.m3-av .m3-fr{position:absolute;left:-16px;top:-16px;width:calc(100% + 32px);height:calc(100% + 32px);pointer-events:none}
.m3-av .ph{width:100%;height:100%;border-radius:50%;overflow:hidden;background:var(--wk-surface2);border:3px solid var(--wk-bg)}
.m3-av img.p{width:100%;height:100%;object-fit:cover;display:block}
.m3-av b{display:grid;place-items:center;width:100%;height:100%;font-size:48px;font-weight:800;color:var(--wk-text2)}
.m3-on{position:absolute;right:6px;bottom:12px;width:22px;height:22px;border-radius:50%;background:#22C55E;border:3px solid var(--wk-bg)}
.m3-id{text-align:center}
.m3-name{display:flex;align-items:center;justify-content:center;gap:8px;font-size:23px;font-weight:800;line-height:1.3;direction:ltr}
.m3-name .v{width:26px;height:26px;flex:none}
.m3-user{margin-top:2px;font-size:14.5px;color:var(--wk-text2);direction:ltr}
.m3-vip{display:inline-block;height:36px;margin-top:10px}
.m3-vip .mi{width:auto;height:36px}
/* level card (left→right exactly like the picture) */
.m3-card{background:var(--wk-surface);border:1px solid var(--wk-border);border-radius:18px}
.m3-lvl{display:flex;align-items:center;gap:12px;margin-top:14px;padding:12px 14px;direction:ltr}
.m3-lvl .bd{width:42px;height:42px;flex:none}
.m3-lvl .lv{font-size:21px;font-weight:800;flex:none;min-width:64px}
.m3-lvl .mid{flex:1;min-width:0}
.m3-lvl .xp{font-size:11.5px;text-align:center;margin-bottom:6px;white-space:nowrap}
.m3-bar{height:9px;border-radius:99px;background:var(--wk-xp-track);overflow:hidden}
.m3-bar i{display:block;height:100%;width:0;border-radius:inherit;background:linear-gradient(90deg,#9B6BFF,#C59BFF);transition:width .9s cubic-bezier(.3,.8,.3,1)}
html[data-wkt]:not([data-wkt=vip_purple]):not([data-wkt=free_dark]) .m3-bar i{background:var(--wk-xp-fill)}
.m3-pct{flex:none;padding:6px 13px;border-radius:99px;font-size:14px;font-weight:800;background:#3A2A6E;color:#D9C6FF}
html[data-wkt]:not([data-wkt=vip_purple]):not([data-wkt=free_dark]) .m3-pct{background:color-mix(in srgb,var(--wk-accent) 28%,transparent);color:var(--wk-text)}
/* three counters: right → left = following · followers · friends */
.m3-cnt{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin-top:12px;padding:16px 4px}
.m3-cnt button{display:flex;align-items:center;justify-content:center;gap:8px;padding:0 4px!important;min-width:0;direction:var(--wk-dir,rtl)}
.m3-cnt button+button{border-right:1px solid var(--wk-border)!important}
.m3-cnt .ci{width:28px;height:28px;flex:none}
.m3-cnt .tx{min-width:0;text-align:center}
.m3-cnt small{display:block;font-size:11.5px;color:var(--wk-text2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.m3-cnt b{display:block;font-size:18px;font-weight:800;margin-top:3px}
/* latest gifts: six places, empty until someone sends a gift */
.m3-gift{margin-top:12px;padding:14px 14px 16px}
.m3-gh{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.m3-gh h3{min-width:0}.m3-gh button{flex:none;white-space:nowrap}
.m3-gh h3{display:flex;align-items:center;gap:10px;margin:0;font-size:17px;font-weight:800}
.m3-gh h3 .gi{width:28px;height:28px}
.m3-gh button{display:flex;align-items:center;gap:6px;font-size:13.5px}
.m3-gh button .ar{width:14px;height:14px}
.m3-slots{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}
.m3-slot{aspect-ratio:.93;border-radius:12px!important;border:1px solid var(--wk-border)!important;background:var(--wk-surface2)!important;display:grid;place-items:center;padding:6px!important;overflow:hidden}
.m3-slot svg,.m3-slot img{width:100%;height:100%;object-fit:contain}
.m3-slot.none{visibility:hidden}
/* menu: right column = VIP · wardrobe · support · info, left column = wallet · stats · security · theme */
.m3-menu{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 10px;margin-top:16px}
.m3-menu button{display:flex;align-items:center;gap:10px;min-height:56px;padding:6px 14px!important;direction:ltr;border-radius:14px!important;background:var(--wk-surface)!important;border:1px solid var(--wk-border)!important}
.m3-menu .mic{width:26px;height:26px;flex:none}
.m3-menu span.t{flex:1;min-width:0;font-size:13.5px;font-weight:600;line-height:1.3;text-align:end;unicode-bidi:plaintext}
.m3-menu .ar{width:13px;height:13px;flex:none;opacity:.85}
.wk3 .si{display:block;width:100%;height:100%}
.m3-sec{margin-top:16px;padding:16px 14px;border-radius:18px;background:var(--wk-surface);border:1px solid var(--wk-border)}
.m3-sh{display:flex;align-items:center;gap:10px;margin:0 0 14px;width:100%}
.m3-sh .hi{width:28px;height:28px;color:var(--wk-accent)}
.m3-sh h3{flex:1;margin:0;font-size:19px;font-weight:800;text-align:start}
.m3-sh .cv{width:20px;height:20px;color:var(--wk-text2)}
.m3-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.m3-st{position:relative;padding:14px 12px!important;border-radius:14px!important;background:var(--wk-surface2)!important;border:1px solid var(--wk-border)!important;text-align:start!important;min-height:92px}
.m3-st .i{position:absolute;top:13px;left:11px;width:22px;height:22px;color:var(--wk-accent)}
.m3-st .i.fl{color:#DDB07A}
.m3-st small{display:block;font-size:12px;color:var(--wk-text2);padding-left:26px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:-.1px}
.m3-st b{display:block;margin-top:14px;font-size:20px;font-weight:800}
.m3-ms{margin-top:16px;padding:0 4px}
.m3-ms .r1{display:flex;justify-content:space-between;align-items:flex-end;gap:8px}
.m3-ms h4{margin:0;font-size:15px;font-weight:700}
.m3-ms small{display:block;margin-top:6px;font-size:12.5px;color:var(--wk-text2)}
.m3-ms .p{font-size:15px;font-weight:700;color:var(--wk-accent);direction:ltr}
.m3-ms .bar{height:8px;margin-top:12px;border-radius:99px;background:var(--wk-xp-track);overflow:hidden;direction:ltr}
.m3-ms .bar i{display:block;height:100%;border-radius:inherit;background:var(--wk-accent);width:0;transition:width .8s ease}
.m3-three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.m3-three button{display:flex;flex-direction:column;align-items:center;gap:12px;padding:16px 6px!important;border-radius:14px!important;background:var(--wk-surface2)!important;border:1px solid var(--wk-border)!important}
.m3-three .i{width:34px;height:34px;color:var(--wk-accent)}
.m3-three .i.u{color:var(--wk-text2)}
.m3-three span.t{font-size:13px;color:var(--wk-text)}
.m3-list{margin-top:2px}
.m3-li{display:flex;align-items:center;gap:14px;width:100%;padding:14px 4px!important}
.m3-li+.m3-li{border-top:1px solid var(--wk-border)!important}
.m3-li .i{width:26px;height:26px;flex:none;color:var(--wk-text2)}
.m3-li span.t{flex:1;font-size:15px;text-align:start}
.m3-li .cv{width:18px;height:18px;flex:none;color:var(--wk-text2)}
