 const leaves=[218,196,174,152,130].map(a=>{const rad=a*Math.PI/180,x=32+23*Math.cos(rad),y=33-23*Math.sin(rad);return `<ellipse cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" rx="3" ry="6.2" transform="rotate(${(90-a+180).toFixed(0)} ${x.toFixed(1)} ${y.toFixed(1)})"/>`}).join('')+`<path d="M24 52A23 23 0 0 1 12 18" fill="none" stroke="url(#${g})" stroke-width="1.6" stroke-linecap="round"/>`;
 const gems='';
