/* ---------- data */
let CARD=null,CTL=null,CARD_OWNER='',LOAD_SEQUENCE=0,LOAD_TASK=null;try{localStorage.removeItem('me3_card')}catch(e){}
function cardOwner(){try{return String(window.WakhanAccountId?.()||ME?.me?.id||'')}catch{return ''}}
function cardAccount(){const id=cardOwner();if(id!==CARD_OWNER){CARD_OWNER=id;CARD=null;CTL=null;LOAD_SEQUENCE++;LOAD_TASK=null;if(id)try{CARD=JSON.parse(localStorage.getItem('me3_card:'+id)||'null')}catch{}}return id}
const W70=()=>{try{return typeof WM70!=='undefined'?WM70:null}catch(e){return null}};
function giftArt(code){try{const w=W70();if(typeof wm70GiftArt==='function'&&w&&w.gifts&&w.gifts.some(v=>v.code===code))return wm70GiftArt(code)}catch(e){}return ''}
function avatarUrl(c){const a=c&&c.avatar;return !a?'':typeof a==='string'?a:(a.url||a.src||'')}
const row=(a,icon,label,cls='')=>`<button data-a="${a}"><span class="mic">${ic(icon,cls)}</span><span class="t">${esc(tx(label))}</span><span class="ar">${ic('arrow')}</span></button>`;

/* ---------- the page, in the reference order */
function page(c,offline){
 const Lv=c.level||{level:1,xp:0,to:20,pct:0},S=c.stats||{},tier=(c.tier&&c.tier.tier)||'free',src=avatarUrl(c);
 const initial=esc((c.name||'W').trim().charAt(0).toUpperCase());
 const got=(c.showcase||[]).filter(Boolean);const slots=[...got,...Array(6).fill(null)].slice(0,6);
 const bg=c.bg&&c.bg.url?c.bg:null;
 return `<main class="wk3${bg?' has-bg':''}">
 ${bg?`<div class="m3-cover" aria-hidden="true"><img src="${esc(bg.url)}" alt="" decoding="async" style="object-position:${+bg.x||50}% ${+bg.y||50}%" onerror="this.parentNode.remove()"><i style="opacity:${Math.min(.8,Math.max(0,+bg.dim||0))}"></i></div>`:''}
 <div class="m3-top">
  <button class="m3-sq l" data-a="settings" aria-label="${esc(tx('settings'))}">${ic('settings')}</button>
  <div class="m3-av"><div class="ph">${src?`<img class="p" src="${esc(src)}" alt="" decoding="async" onerror="this.outerHTML='<b>${initial}</b>'">`:`<b>${initial}</b>`}</div><i class="m3-on"></i></div>
  <button class="m3-sq r" data-a="edit" aria-label="${esc(tx('edit'))}">${ic('edit_profile')}</button>
 </div>
 ${offline?`<p class="m3-off">${esc(tx('offline'))}</p>`:''}
 <section class="m3-id">
  <div class="m3-name"><span dir="auto">${esc(c.name||'Wakhan')}</span>${c.verified?`<span class="v">${ic('verified_badge','keep')}</span>`:''}</div>
  ${c.username?`<div class="m3-user">@${esc(c.username)}</div>`:''}
  ${window.WK2_BADGES?WK2_BADGES.html({role:c.role,tier,tap:'vip'}):(tier!=='free'?`<button class="m3-vip" data-a="vip" aria-label="VIP">${ic('vip_badge','keep')}</button>`:'')}
 </section>
 <div class="m3-card m3-lvl" data-a="level" role="button" tabindex="0" style="cursor:pointer">
  <span class="bd">${rankBadge(Lv.level)}</span><span class="lv">Lv.${num(Lv.level)}</span>
  <div class="mid"><div class="xp">XP: ${num(Lv.xp)} / ${num(Lv.to)}</div><div class="m3-bar"><i data-w="${Number(Lv.pct)||0}"></i></div></div>
  <span class="m3-pct">${num(Lv.pct)}%</span>
 </div>
 <div class="m3-card m3-cnt">
  <button data-a="following"><span class="tx"><small>${esc(tx('following'))}</small><b>${num(S.following)}</b></span><span class="ci">${ic('following')}</span></button>
  <button data-a="followers"><span class="tx"><small>${esc(tx('followers'))}</small><b>${num(S.followers)}</b></span><span class="ci">${ic('followers')}</span></button>
  <button data-a="friends"><span class="tx"><small>${esc(tx('friends'))}</small><b>${num(S.friends)}</b></span><span class="ci">${ic('friends')}</span></button>
 </div>
 <div class="m3-card m3-gift">
  <div class="m3-gh"><h3><span class="gi">${GIFT}</span>${esc(tx('gifts'))}</h3><button data-a="gifts">${esc(tx('allGifts'))}<span class="ar">${ic('arrow')}</span></button></div>
  <div class="m3-slots">${slots.map(g=>g?`<button class="m3-slot" data-a="gifts">${giftArt(g.code)}</button>`:`<span class="m3-slot none" aria-hidden="true"></span>`).join('')}</div>
 </div>
 <div class="m3-menu">
  ${row('vip','vip_subscription','vip')}${row('wallet','wallet_baksak','wallet')}
  ${row('closet','wardrobe','closet')}${row('stats','activity_stats','stats')}
 </div>
 ${lower(c)}
 ${CTL&&CTL.role?`<button class="m3-ctl" data-a="control"><span class="k"><img src="/s/wk2/ctl_crown.svg${V}" alt=""></span><span><b>${esc(tx('control'))}</b><small>${esc(tx('controlSub'))}</small></span><span class="own">${esc(CTL.role==='owner'?'OWNER':String(CTL.role).replace('_',' ').toUpperCase())}</span></button>`:''}
</main>`}



/* ---------- level & rank: a badge for every rank, the level-up moment, the rank-up moment, +XP */
const RANKS=[['newcomer',1,'#C9CFD9','#7B8494'],['bronze',11,'#F1B98A','#8E5427'],['silver',21,'#F4F7FB','#8C9DB0'],['gold',31,'#FFE7A0','#C9921C'],['platinum',41,'#C7F5F7','#3E9FAA'],
 ['diamond',51,'#CFE3FF','#3D7BEA'],['master',61,'#E6D6FF','#7C4FD6'],['legend',71,'#FFD1E8','#C23F84'],['emperor',81,'#FFC9C3','#B23A33'],['sovereign',91,'#FFF1B8','#C9A23A']];
const rankOf=l=>{let r=RANKS[0];for(const x of RANKS)if(l>=x[1])r=x;return r};
let RG=0;
function rankBadge(level){const r=rankOf(level||1),i=RANKS.indexOf(r),g='rb'+(++RG);
 const leaves=[218,196,174,152,130].map(a=>{const rad=a*Math.PI/180,x=32+23*Math.cos(rad),y=33-23*Math.sin(rad);return `<ellipse cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" rx="3" ry="6.2" transform="rotate(${(90-a+180).toFixed(0)} ${x.toFixed(1)} ${y.toFixed(1)})"/>`}).join('')+`<path d="M24 52A23 23 0 0 1 12 18" fill="none" stroke="url(#${g})" stroke-width="1.6" stroke-linecap="round"/>`;
 const gems='';
 const crown=i>=8?`<path d="M23 9l3 4 6-6 6 6 3-4-1.6 8H24.6z" fill="url(#${g})" stroke="${r[3]}" stroke-width=".8"/>`:'';
 return `<svg class="rkb" viewBox="0 0 64 64" aria-label="${esc(tx('r_'+r[0]))}"><defs><linearGradient id="${g}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${r[2]}"/><stop offset="1" stop-color="${r[3]}"/></linearGradient></defs>
 <g fill="url(#${g})">${leaves}<g transform="translate(64 0) scale(-1 1)">${leaves}</g></g>
 <path d="M32 18l4.1 8.4 9.3 1.3-6.7 6.5 1.6 9.2L32 39l-8.3 4.4 1.6-9.2-6.7-6.5 9.3-1.3z" fill="url(#${g})" stroke="${r[3]}" stroke-width=".9" stroke-linejoin="round"/>
 ${i>=2?`<path d="M32 22.5l2.6 5.3" stroke="#fff" stroke-width="1.4" stroke-linecap="round" opacity=".7"/>`:''}${gems}${crown}
 <path d="M24 52q8 4 16 0" fill="none" stroke="url(#${g})" stroke-width="2.4" stroke-linecap="round"/></svg>`}
const UNLOCK={11:'u_fx_glow',21:'u_crown_silver',31:'u_crown_gold'};
function celebrate(from,to){
 if(to<=from)return;const rNew=rankOf(to),rOld=rankOf(from),rankUp=rNew[0]!==rOld[0];
 const gained=Object.keys(UNLOCK).map(Number).filter(l=>l>from&&l<=to).map(l=>tx(UNLOCK[l]));
 const lite=(()=>{try{return (navigator.deviceMemory&&navigator.deviceMemory<=3)||matchMedia('(prefers-reduced-motion: reduce)').matches}catch(e){return false}})();
 const dots=lite?'':Array.from({length:14},(_,k)=>`<i style="--a:${k*360/14}deg;--d:${(k%3)*60}ms"></i>`).join('');
 const o=document.createElement('div');o.className='m3-cel'+(rankUp?' rk':'');o.style.setProperty('--c1',rNew[2]);o.style.setProperty('--c2',rNew[3]);
 o.innerHTML=`<div class="box"><div class="bg">${dots}<span class="b">${rankBadge(to)}</span></div>
  ${rankUp?`<small class="nr">${esc(tx('rankUp'))}</small><h2 style="color:${rNew[2]}">${esc(tx('r_'+rNew[0]))}</h2>`:''}
  <p class="t">${esc(tx('lvlUp',{n:num(to)}))}</p>
  ${gained.length?`<div class="un">${gained.map(g=>`<span>🎁 ${esc(g)} · ${esc(tx('unlocked'))}</span>`).join('')}</div>`:''}
  <small class="cl">${esc(tx('tapClose'))}</small></div>`;
 document.body.appendChild(o);try{hap('success')}catch(e){}
 const close=()=>{o.classList.add('out');setTimeout(()=>o.remove(),260)};o.onclick=close;setTimeout(close,rankUp?3600:2400)}
function xpPop(n){const bar=document.querySelector('.wk3 .m3-lvl .mid');if(!bar||!(n>0))return;const s=document.createElement('span');s.className='m3-xpp';s.textContent='+'+num(n)+' XP';bar.appendChild(s);setTimeout(()=>s.remove(),1600)}
function progressCheck(c){try{const L=c&&c.level;if(!L)return;const k='me3_lvl_'+(c.uid||'');const prev=JSON.parse(localStorage.getItem(k)||'null');
 localStorage.setItem(k,JSON.stringify({l:L.level,x:L.xp}));if(!prev)return;
 if(L.level>prev.l)setTimeout(()=>celebrate(prev.l,L.level),450);else if(L.xp>prev.x)setTimeout(()=>xpPop(L.xp-prev.x),500)}catch(e){}}
/* ---------- the four lower sections (real numbers from the server) */
const li=(a,icon,label,cls='')=>`<button class="m3-li ${cls}" data-a="${a}"><span class="i">${sv(icon)}</span><span class="t">${esc(tx(label))}</span><span class="cv">${sv('chevron-left')}</span></button>`;
function lower(c){const A=c.activity||{};const tot=A.missions_total||0,done=A.missions_done||0,pct=tot?Math.round(done*100/tot):0;
 return `<section class="m3-sec">
  <button class="m3-sh" data-a="activity"><span class="hi">${sv('target')}</span><h3>${esc(tx('act'))}</h3><span class="cv">${sv('chevron-left')}</span></button>
  <div class="m3-two">
   <button class="m3-st" data-a="trophies"><span class="i">${sv('award')}</span><small>${esc(tx('ach'))}</small><b>${esc(tx('badges',{n:num(A.achievements)}))}</b></button>
   <button class="m3-st" data-a="streak"><span class="i fl">${sv('flame')}</span><small>${esc(tx('streak'))}</small><b>${esc(tx('days',{n:num(A.streak)}))}</b></button>
  </div>
  <button class="m3-ms" data-a="quests" style="display:block;width:100%"><div class="r1"><div><h4>${esc(tx('today'))}</h4><small>${esc(tx('ofm',{a:num(done),b:num(tot)}))}</small></div><span class="p">${pct}%</span></div><div class="bar"><i data-w="${pct}"></i></div></button>
 </section>
 <section class="m3-sec">
  <button class="m3-sh" data-a="collection"><span class="hi">${sv('layers')}</span><h3>${esc(tx('coll'))}</h3><span class="cv">${sv('chevron-left')}</span></button>
  <div class="m3-three" style="grid-template-columns:1fr 1fr">
   <button data-a="special"><span class="i">${sv('gem')}</span><span class="t">${esc(tx('special'))}</span></button>
   <button data-a="medals"><span class="i">${sv('medal')}</span><span class="t">${esc(tx('medals'))}</span></button>
  </div>
 </section>`}
/* ---------- actions: inner pages come one by one; until then the working screens open */
const ACT={};['level','settings','edit','vip','wallet','closet','stats','support','security','info','theme','gifts','friends','followers','following','control','activity','trophies','streak','quests','collection','special','medals','requests','search','blocked','about'].forEach(k=>ACT[k]=()=>open(k));
ACT.lang=()=>{try{if(typeof window.langSheet==='function')return window.langSheet()}catch(e){}try{langSheet()}catch(e){}};
ACT.terms=()=>{const u=location.origin+'/terms';try{if(window.Capacitor&&Capacitor.Plugins&&Capacitor.Plugins.Browser)return Capacitor.Plugins.Browser.open({url:u})}catch(e){}window.open(u,'_blank')};
ACT.share=async()=>{const c=CARD||{};const u=location.origin+'/u/'+encodeURIComponent(c.username||c.wid||'');try{if(navigator.share)return await navigator.share({title:'WAKHAN',text:tx('shareText'),url:u})}catch(e){return}try{await navigator.clipboard.writeText(u);say(u)}catch(e){}};
ACT.logout=()=>{try{if(window.WAKHAN_NATIVE_N1&&WAKHAN_NATIVE_N1.logout)return WAKHAN_NATIVE_N1.logout()}catch(e){}if(!confirm(tx('logoutAsk')))return;try{if(window.wkaLogout)return wkaLogout()}catch(e){}const b=document.querySelector('.wka-out');if(b)b.click()};
function open(name){const f=window.ME3_PAGES&&ME3_PAGES[name];if(f)return f(CARD||{});
 const old={friends:()=>wm70OpenFriends(),requests:()=>wm70OpenFriends(),search:()=>wm70OpenFriends(),frames:()=>wm70Edit('halos'),wallet:()=>wc23Open(),vip:()=>go('s'),closet:()=>wm70Edit('halos'),edit:()=>wt30Edit(),support:()=>helpSheet()}[name];
 if(old){try{old();return}catch(e){}}say(tx('soon'))}
function bind(root){root.onclick=e=>{const b=e.target.closest('[data-a]');if(!b)return;try{hap()}catch(_){}const f=ACT[b.dataset.a];if(f)f()};
 requestAnimationFrame(()=>requestAnimationFrame(()=>{root.querySelectorAll('.m3-bar i,.m3-ms .bar i').forEach(b=>b.style.width=b.dataset.w+'%')}))}
function host(){try{if(window.WakhanPages&&WakhanPages.view)return WakhanPages.view()}catch(e){}return document.getElementById('view')}
function draw(offline){try{if(typeof TAB!=='undefined'&&TAB!=='m')return}catch{}const v=host();if(!v)return;
 const c=CARD||{name:(window.ME&&ME.me&&ME.me.name)||'',level:{level:1,xp:0,to:20,pct:0},stats:{},showcase:[]};
 const markup=page(c,offline);if(v.__me3Markup!==markup||!v.querySelector('.wk3')){v.innerHTML=markup;v.__me3Markup=markup;bind(v.querySelector('.wk3'))}document.body.classList.add('wk3-on')}
async function gifts(){try{const w=W70();if(w&&w.gifts&&w.gifts.length)return;const r=await api('/api/app/gifts');if(r&&r.ok&&w){w.gifts=r.gifts;if(CARD&&(CARD.showcase||[]).some(Boolean))draw(false)}}catch(e){}}
async function load(){const id=cardAccount();if(!id)return;if(LOAD_TASK)return LOAD_TASK;const serial=++LOAD_SEQUENCE;gifts();const task=(async()=>{try{const [r,k]=await Promise.all([api('/api/app/me/card'),api('/api/ctl/me').catch(()=>null)]);if(serial!==LOAD_SEQUENCE||id!==cardOwner())return;CTL=k&&k.ok?k:null;if(r&&r.ok){CARD=r;try{localStorage.setItem('me3_card:'+id,JSON.stringify(r))}catch{}draw(false);progressCheck(r)}else if(CARD)draw(true)}catch{if(serial===LOAD_SEQUENCE&&CARD)draw(true)}finally{if(LOAD_TASK===task)LOAD_TASK=null}})();LOAD_TASK=task;return task}
