 b.addEventListener('click',e=>{const x=e.target.closest('[data-bn]');if(!x)return;if(x.dataset.bn==='in')knGo(code);else knBannerOff()});setTimeout(()=>{if(b.isConnected)knBannerOff()},20000)}
