   <button class="tl-x" data-x="hdel" data-id="${esc(x.id)}" data-ep="${esc(x.ep||'')}" aria-label="${esc(tx('removeOne'))}">${sv('x')}</button></div>`}).join('')}`).join('')}</div>`;
 return out}
