const now=()=>Date.now()+S.off;
const on=()=>!!(S.st&&S.st.asset);
function emit(){try{const k=K();k&&k.repaint&&k.repaint()}catch(e){}try{window.dispatchEvent(new CustomEvent('wkm',{detail:S.st}))}catch(e){}}

/* ---------- the one media element (kept between tracks so iOS keeps its permission to play) */
function media(kind){if(S.el&&S.kind===kind)return S.el;stopEl();if(S.el)S.el.remove();
