 e.className=kind==='video'?'r-nv wkm-v':'wkm-a';if(kind!=='video'){e.style.cssText='position:fixed;left:0;bottom:0;width:1px;height:1px;opacity:.01;pointer-events:none';document.body.appendChild(e)}
 e.addEventListener('error',()=>retry());e.addEventListener('waiting',()=>{S.wait=Date.now()});e.addEventListener('playing',()=>{S.wait=0;S.blocked=false});
 S.el=e;S.kind=kind;S.url='';return e}
function setSrc(url){const e=S.el;if(!e||!url)return;const full=abs(url)+(S.saver?'?q=low':'');if(S.url===full)return;S.url=full;
 if(S.hls){try{S.hls.destroy()}catch(_){}S.hls=null}
 if(e.canPlayType('application/vnd.apple.mpegurl')){e.src=full;return}                       // iPhone: native HLS, picks the quality itself
 if(window.Hls&&window.Hls.isSupported()){const h=new window.Hls({maxBufferLength:30,backBufferLength:30});h.loadSource(full);h.attachMedia(e);S.hls=h;
  h.on(window.Hls.Events.ERROR,(_,d)=>{if(!d||!d.fatal)return;if(d.type==='networkError')h.startLoad();else if(d.type==='mediaError')h.recoverMediaError();else retry()});return}
 e.src=full}
function stopEl(){const e=S.el;clearTimeout(S.startT);if(!e)return;try{e.pause()}catch(_){}if(S.hls){try{S.hls.destroy()}catch(_){}S.hls=null}try{e.removeAttribute('src');e.load()}catch(_){}S.url=''}
function retry(){if(!on())return;clearTimeout(S.rm);S.rm=setTimeout(()=>{S.url='';if(S.st&&S.st.url)setSrc(S.st.url);tick()},1500)}
function rate(r){const e=S.el;if(e&&Math.abs((e.playbackRate||1)-r)>0.001)try{e.playbackRate=r}catch(_){}}

/* ---------- follow the server clock */
function target(){const s=S.st;if(!on())return 0;if(!s.playing||s.t0==null)return Number(s.paused_at)||0;return Math.max(0,(now()-s.t0)/1000)}
function tick(){const s=S.st,e=S.el;if(!on()||!e)return;timeUi();if(!s.ready)return;
 if(!s.playing){if(!e.paused)e.pause();rate(1);if(Math.abs((e.currentTime||0)-(Number(s.paused_at)||0))>0.3)try{e.currentTime=Number(s.paused_at)||0}catch(_){}return}
 if(s.t0>now()+40){if(!e.paused)e.pause();clearTimeout(S.startT);S.startT=setTimeout(tick,Math.max(0,s.t0-now()));return}   // a start announced ahead: everyone begins on the same moment
