async function connect(){const code=S.code;if(!code)return;clearTimeout(S.rt);let j=null;
 try{j=await api('/api/media/ticket',{code})}catch(_){}
 if(S.code!==code)return;if(j&&!j.ok&&(j.err==='http'||j.err==='not_found')){clearTimeout(S.rt);S.rt=setTimeout(connect,60000);return}   // a server without the media engine: ask again in a minute, quietly
 if(!j||!j.ok){later();return}
 let ws;try{ws=new WebSocket(abs(j.url).replace(/^http/,'ws'))}catch(_){later();return}
