 ws.onopen=()=>{if(S.ws!==ws)return;S.tries=0;stopPoll();pings();if(S.st)send({type:'resume',v:S.st.v})};
 ws.onclose=()=>{if(S.ws===ws){S.ws=null;later()}};ws.onerror=()=>{try{ws.close()}catch(_){}}}
