.s6-mur{overflow-y:auto;-webkit-overflow-scrolling:touch;display:flex;flex-direction:column;gap:6px;padding-bottom:10px;min-height:60px}
.s6-mi{display:flex;align-items:center;gap:10px;padding:6px 4px;animation:s6in .3s both;animation-delay:calc(var(--k)*35ms)}
.s6-mth{position:relative;width:52px;height:52px;border-radius:14px;overflow:hidden;flex:none;background:linear-gradient(135deg,rgba(255,255,255,.12),rgba(255,255,255,.04));display:grid;place-items:center;color:rgba(255,255,255,.6)}
.s6-mth svg{width:22px;height:22px}.s6-mth img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.s6-mtt{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px}
.s6-mtt b{font-size:14px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.s6-mtt small{display:flex;align-items:center;gap:6px;font-size:11.5px;opacity:.85;white-space:nowrap;overflow:hidden}
.s6-mtt small bdi{overflow:hidden;text-overflow:ellipsis;opacity:.8}
.s6-sb{font-style:normal;font-size:10px;font-weight:900;padding:2px 7px;border-radius:6px;flex:none;color:#fff}
.s6-sbs{background:#ff7a1a}.s6-sby{background:#e5202e}
.s6-ma,.s6-mp{flex:none;width:40px;height:40px;border-radius:50%;display:grid;place-items:center;padding:0}
.s6-ma{border:1.5px solid rgba(255,255,255,.4)!important;background:transparent!important;color:#fff}.s6-ma svg{width:18px;height:18px}
.s6-ma.s6-done{border-color:#9ff5d2!important;color:#9ff5d2}
.s6-mp{background:#fff!important;color:#14101c!important;border:0}.s6-mp svg{width:18px;height:18px}
.s6-mp:active,.s6-ma:active{transform:scale(.9)}
.s6-mul{display:flex;justify-content:center;gap:6px;padding:22px 0}.s6-mul i{width:8px;height:8px;border-radius:50%;background:#fff;opacity:.3;animation:s6mul 1s infinite}.s6-mul i:nth-child(2){animation-delay:.15s}.s6-mul i:nth-child(3){animation-delay:.3s}
@keyframes s6mul{50%{opacity:1;transform:translateY(-4px)}}
.s6-mue{text-align:center;opacity:.6;font-size:13px;padding:18px 0}
.s6-mug{display:flex;flex-direction:column;align-items:center;gap:14px;padding:18px 6px 10px;text-align:center}
.s6-mgi{width:58px;height:58px;border-radius:50%;display:grid;place-items:center;border:1.5px solid rgba(255,255,255,.4)}.s6-mgi svg{width:26px;height:26px}
.s6-mug>b{font-size:16px;font-weight:900}
.s6-mgb{display:flex;gap:10px;width:100%}
.s6-mgb button{flex:1;height:50px;border-radius:25px;display:flex;align-items:center;justify-content:center;gap:8px;font:inherit;font-size:14px;font-weight:900}
.s6-mgb svg{width:19px;height:19px}
.s6-mgr{background:#fff!important;color:#14101c!important;border:0}.s6-mgr[disabled]{opacity:.6}
.s6-mgs{background:transparent!important;color:#fff!important;border:1.5px solid rgba(255,255,255,.45)!important}
.s6-sbw{background:linear-gradient(135deg,#3ee6c4,#2a7bff)}
.s6-kbon .s6-sh .s6-bx{padding-bottom:8px}
.s6-mur:empty{min-height:0;padding-bottom:0}
.s6-kbon .s6-mus{margin-bottom:4px}

