/* ---- WAKHAN media client (0.2.73): tracks and films streamed from the WAKHAN server (HLS, several qualities), kept on the same
   second for everyone in the salon through the salon socket. The server clock is the only clock: the phone measures its offset
   with a few pings, then follows t0 (the server moment of second 0) — small gaps are closed by playing 5% faster/slower, big
   ones by a jump. The socket comes back by itself (0.5 s, 1 s, 2 s … 15 s), with a 3-second HTTP poll while it is away. */
(()=>{'use strict';if(window.WKM)return;
const K=()=>window.SLR3&&window.SLR3.k;
const ORIGIN=()=>window.WKM_ORIGIN||'';
const abs=p=>{try{return new URL(p,ORIGIN()||document.baseURI).href}catch(e){return p}};
const me=()=>{try{return Number(K().me())||0}catch(e){return 0}};
const S={code:'',ws:null,st:null,off:0,rtt:1e9,tries:0,rt:0,poll:0,el:null,kind:'',url:'',hls:null,startT:0,rm:0,blocked:false,saver:false,err:'',seen:0};
try{S.saver=localStorage.getItem('wkm_saver')==='1'}catch(e){}
const now=()=>Date.now()+S.off;
const on=()=>!!(S.st&&S.st.asset);
function emit(){try{const k=K();k&&k.repaint&&k.repaint()}catch(e){}try{window.dispatchEvent(new CustomEvent('wkm',{detail:S.st}))}catch(e){}}

/* ---------- the one media element (kept between tracks so iOS keeps its permission to play) */
function media(kind){if(S.el&&S.kind===kind)return S.el;stopEl();if(S.el)S.el.remove();
 const e=document.createElement(kind==='video'?'video':'audio');e.setAttribute('playsinline','');e.setAttribute('webkit-playsinline','');e.preload='auto';
 e.className=kind==='video'?'r-nv wkm-v':'wkm-a';if(kind!=='video'){e.style.cssText='position:fixed;left:0;bottom:0;width:1px;height:1px;opacity:.01;pointer-events:none';document.body.appendChild(e)}
 e.addEventListener('error',()=>retry());e.addEventListener('waiting',()=>{S.wait=Date.now()});e.addEventListener('playing',()=>{S.wait=0;S.blocked=false});
 S.el=e;S.kind=kind;S.url='';return e}
function setSrc(url){const e=S.el;if(!e||!url)return;const full=abs(url)+(S.saver?'?q=low':'');if(S.url===full)return;S.url=full;
 if(S.hls){try{S.hls.destroy()}catch(_){}S.hls=null}
 if(e.canPlayType('application/vnd.apple.mpegurl')){e.src=full;return}                       // iPhone: native HLS, picks the quality itself
 if(window.Hls&&window.Hls.isSupported()){const h=new window.Hls({maxBufferLength:30,backBufferLength:30});h.loadSource(full);h.attachMedia(e);S.hls=h;
  h.on(window.Hls.Events.ERROR,(_,d)=>{if(!d||!d.fatal)return;if(d.type==='networkError')h.startLoad();else if(d.type==='mediaError')h.recoverMediaError();else retry()});return}
 e.src=full}
function stopEl(){const e=S.el;clearTimeout(S.startT);if(!e)return;try{e.pause()}catch(_){}if(S.hls){try{S.hls.destroy()}catch(_){}S.hls=null}try{e.removeAttribute('src');e.load()}catch(_){}S.url=''}
function retry(){if(!on())return;clearTimeout(S.rm);S.rm=setTimeout(()=>{S.url='';if(S.st&&S.st.url)setSrc(S.st.url);tick()},1500)}
function rate(r){const e=S.el;if(e&&Math.abs((e.playbackRate||1)-r)>0.001)try{e.playbackRate=r}catch(_){}}

/* ---------- follow the server clock */
function target(){const s=S.st;if(!on())return 0;if(!s.playing||s.t0==null)return Number(s.paused_at)||0;return Math.max(0,(now()-s.t0)/1000)}
function tick(){const s=S.st,e=S.el;if(!on()||!e)return;timeUi();if(!s.ready)return;
 if(!s.playing){if(!e.paused)e.pause();rate(1);if(Math.abs((e.currentTime||0)-(Number(s.paused_at)||0))>0.3)try{e.currentTime=Number(s.paused_at)||0}catch(_){}return}
 if(s.t0>now()+40){if(!e.paused)e.pause();clearTimeout(S.startT);S.startT=setTimeout(tick,Math.max(0,s.t0-now()));return}   // a start announced ahead: everyone begins on the same moment
 const t=target();if(s.duration&&t>=s.duration){if(!e.paused)e.pause();return}
 const d=(e.currentTime||0)-t;
 if(e.paused||Math.abs(d)>1){try{if(Math.abs(d)>0.25)e.currentTime=t}catch(_){}rate(1);const p=e.play();if(p&&p.catch)p.catch(()=>{if(!S.blocked){S.blocked=true;emit()}});return}
 rate(Math.abs(d)>0.15?(d>0?0.95:1.05):1)}
function timeUi(){if(!S.st||S.kind!=='video')return;const r=document.querySelector('#view .slr');if(!r||!r.querySelector('.wkm-st'))return;const t=Math.min(target(),S.st.duration||1e9),d=S.st.duration||0;
 const f=x=>{x=Math.max(0,Math.floor(x));return Math.floor(x/60)+':'+String(x%60).padStart(2,'0')},w=(d?Math.min(100,t/d*100):0).toFixed(1)+'%',ta=f(t),tb=f(d);
 r.querySelectorAll('.r-t0').forEach(a=>{if(a.textContent!==ta)a.textContent=ta});r.querySelectorAll('.r-t1').forEach(b=>{if(b.textContent!==tb)b.textContent=tb});r.querySelectorAll('.r-sk i').forEach(i=>{if(i.style.width!==w)i.style.width=w})}

function apply(st){const was=S.st;S.st=st;S.err='';
 if(!st||!st.asset){stopEl();emit();return}
 media(st.kind==='video'?'video':'audio');if(st.url)setSrc(st.url);meta();tick();
 if(!was||was.asset!==st.asset||was.playing!==st.playing||was.ready!==st.ready||was.title!==st.title)emit()}
function meta(){const s=S.st;if(!s||!('mediaSession' in navigator))return;try{
 navigator.mediaSession.metadata=new window.MediaMetadata({title:s.title||'',artist:s.artist||'WAKHAN',artwork:s.thumb?[{src:s.thumb,sizes:'512x512'}]:[]});
 const c=!!s.control,H=(a,f)=>{try{navigator.mediaSession.setActionHandler(a,c?f:null)}catch(_){}};
 H('play',()=>ctl('play'));H('pause',()=>ctl('pause'));H('stop',()=>ctl('stop'));H('seekto',d=>ctl('seek',d&&d.seekTime))}catch(_){}}

/* ---------- the salon socket */
function send(o){try{if(S.ws&&S.ws.readyState===1){S.ws.send(JSON.stringify(o));return true}}catch(_){}return false}
function pings(){S.rtt=1e9;for(let i=0;i<5;i++)setTimeout(()=>send({type:'ping',c:Date.now()}),i*160)}
function onMsg(ev){let m;try{m=JSON.parse(ev.data)}catch(_){return}
 if(m.type==='hello'){if(S.rtt>=1e9)S.off=m.now-Date.now()}
 else if(m.type==='pong'){const rtt=Date.now()-m.c;if(rtt<=S.rtt){S.rtt=rtt;S.off=m.s-(m.c+rtt/2)}tick()}
 else if(m.type==='state')apply(m.state);
 else if(m.type==='error'){S.err=m.err||'';emit()}}
async function connect(){const code=S.code;if(!code)return;clearTimeout(S.rt);let j=null;
 try{j=await api('/api/media/ticket',{code})}catch(_){}
 if(S.code!==code)return;if(j&&!j.ok&&(j.err==='http'||j.err==='not_found')){clearTimeout(S.rt);S.rt=setTimeout(connect,60000);return}   // a server without the media engine: ask again in a minute, quietly
 if(!j||!j.ok){later();return}
 let ws;try{ws=new WebSocket(abs(j.url).replace(/^http/,'ws'))}catch(_){later();return}
 S.ws=ws;ws.onmessage=onMsg;
 ws.onopen=()=>{if(S.ws!==ws)return;S.tries=0;stopPoll();pings();if(S.st)send({type:'resume',v:S.st.v})};
 ws.onclose=()=>{if(S.ws===ws){S.ws=null;later()}};ws.onerror=()=>{try{ws.close()}catch(_){}}}
function later(){if(!S.code)return;clearTimeout(S.rt);const d=Math.min(15000,500*Math.pow(2,S.tries++));S.rt=setTimeout(connect,d);if(S.tries>=3)startPoll()}
function startPoll(){if(S.poll)return;const go=async()=>{if(!S.code)return;try{const j=await api('/api/media/state?code='+encodeURIComponent(S.code));if(j&&j.ok&&(!S.st||j.state.v!==S.st.v))apply(j.state)}catch(_){}};go();S.poll=setInterval(go,3000)}
function stopPoll(){clearInterval(S.poll);S.poll=0}
function attach(code){S.code=code;S.tries=0;S.st=null;connect()}
function detach(){const had=on();S.code='';clearTimeout(S.rt);stopPoll();const ws=S.ws;S.ws=null;try{ws&&ws.close()}catch(_){}stopEl();S.st=null;if(had)emit()}

/* ---------- actions */
async function ctl(a,pos,code){code=code||S.code;if(!code)return false;
 if(code===S.code&&send({type:'ctl',a,pos}))return true;
 try{const j=await api('/api/media/ctl',{code,a,pos});if(j&&j.ok){if(code===S.code)apply(j.state);return true}S.err=(j&&j.err)||'x'}catch(_){S.err='offline'}return false}
async function play(src,ref){const code=S.code||(K()&&K().cid());if(!code)throw Error('nothing');
 const j=await api('/api/media/play',{code,src,ref});if(!j||!j.ok)throw Error((j&&j.err)||'x');if(j.state)apply(j.state);return j}
async function search(q,src){const j=await api('/api/media/search?src='+encodeURIComponent(src||'up')+'&q='+encodeURIComponent(q));return (j&&j.ok&&j.items)||[]}
function attachVideo(host){const e=S.el;if(!host||!e||S.kind!=='video')return;if(e.parentElement!==host){host.appendChild(e);tick()}}

/* ---------- life */
setInterval(()=>{let code=null;try{code=K()&&K().cid()}catch(_){}code=code?String(code):'';
 if(code!==S.code){detach();if(code)attach(code)}
 if(on()){tick();if(S.kind==='video'){const h=document.querySelector('#view .slr .wkm-vh');if(h)attachVideo(h)}}},700);
setInterval(()=>{if(S.ws)send({type:'ping',c:Date.now()})},30000);
document.addEventListener('visibilitychange',()=>{if(document.hidden||!S.code)return;if(!S.ws){S.tries=0;connect()}else{pings();if(S.st)send({type:'resume',v:S.st.v})}tick()});
document.addEventListener('pointerdown',()=>{if(S.blocked){S.blocked=false;tick()}},true);
window.addEventListener('online',()=>{if(S.code&&!S.ws){S.tries=0;connect()}});

window.WKM={on,st:()=>S.st,video:()=>on()&&S.kind==='video',mine:()=>on()&&Number(S.st.by)===me(),control:()=>!!(S.st&&S.st.control),
 ctl,play,search,attachVideo,ui:timeUi,el:()=>S.el,pos:target,blocked:()=>S.blocked,err:()=>S.err,offset:()=>S.off,
 saver:v=>{if(v===undefined)return S.saver;S.saver=!!v;try{localStorage.setItem('wkm_saver',v?'1':'0')}catch(_){}if(S.st&&S.st.url){S.url='';setSrc(S.st.url)}}};
})();

