 e.addEventListener('error',()=>retry());e.addEventListener('waiting',()=>{S.wait=Date.now()});e.addEventListener('playing',()=>{S.wait=0;S.blocked=false});
 S.el=e;S.kind=kind;S.url='';return e}
function setSrc(url){const e=S.el;if(!e||!url)return;const full=abs(url)+(S.saver?'?q=low':'');if(S.url===full)return;S.url=full;
 if(S.hls){try{S.hls.destroy()}catch(_){}S.hls=null}
 if(e.canPlayType('application/vnd.apple.mpegurl')){e.src=full;return}                       // iPhone: native HLS, picks the quality itself
