 const cnt=d=>{const e=w.querySelector('.s6-qn');if(!e||!d)return;const n=(d.next||[]).length;e.hidden=!n;e.textContent=t6('videos',{n:num(n)})};cnt(Q.d);loadQ().then(cnt);
 const lr=w.querySelector('.s6-lr');
 const res=()=>{if(!item){lr.innerHTML='';return}lr.innerHTML=`<div class="s6-pv"><span class="s6-th"><img src="${esc(item.thumb||'')}" alt=""></span><span class="s6-tt"><b><bdi>${esc(item.title||'')}</bdi></b><small>${srcH(item.src)}</small></span></div>
