 w.addEventListener('submit',e=>{e.preventDefault();check()});
 w.addEventListener('paste',e=>{if(e.target.matches('.s6-lf input'))setTimeout(check,30)});
 w.addEventListener('click',async e=>{if(e.target===w)return shut(w);const b=e.target.closest('[data-s]');if(!b||b.disabled)return;const a=b.dataset.s;hap();
