  if(a==='link'){const f=w.querySelector('.s6-lf');f.hidden=!f.hidden;w.querySelector('.s6-lk').classList.toggle('s6-open',!f.hidden);if(!f.hidden)setTimeout(()=>f.querySelector('input').focus(),40);return}
