/* ---------- the queue page: now playing, up next (owner drags and removes), friends' suggestions (owner approves) */
/* bottom sheets with a text field (salon name, link, report…) rise above the iPhone keyboard; the app reports the keyboard itself */
(()=>{let cap=null;const set=()=>{const a=document.activeElement;const on=!!(a&&a.matches&&a.matches('input:not([type=range]):not([type=file]),textarea')&&a.closest('.s6-sh'));let kb=0;
 if(on&&!document.documentElement.classList.contains('wk-android')){const k=window.WakhanKeyboard&&WakhanKeyboard.viewport&&WakhanKeyboard.viewport();if(k&&k.fullHeight)kb=Math.max(0,Math.round(k.fullHeight-k.height));
  if(!kb&&cap)kb=Math.max(0,cap-((screen.height-innerHeight)>60?34:0));if(!kb&&window.visualViewport)kb=Math.max(0,Math.round(innerHeight-visualViewport.height-visualViewport.offsetTop))}
 document.documentElement.style.setProperty('--skb',kb+'px');document.documentElement.classList.toggle('s6-kbon',kb>0)};
 /* iPhone scrolls the whole app up to show the field; the sheet already rises by itself, so the app is held in place and put back
    exactly where it was when the keyboard closes (otherwise the next pages open under the clock) */
 let keep=null;const field=t=>t&&t.matches&&t.matches('input:not([type=range]):not([type=file]),textarea')&&t.closest('.s6-sh,.slr-pg,.s8-cr');
 const hold=()=>{if(keep==null)return;try{if(Math.abs(scrollY-keep)>1||(window.visualViewport&&visualViewport.offsetTop>0))window.scrollTo(0,keep)}catch(e){}};
 addEventListener('focusin',e=>{if(field(e.target)){if(keep==null)keep=scrollY;[60,250,500].forEach(t=>setTimeout(hold,t))}set();setTimeout(set,120);setTimeout(set,450)});
 addEventListener('focusout',e=>{setTimeout(()=>{set();if(keep!=null&&!field(document.activeElement)){hold();setTimeout(()=>{hold();keep=null},350)}},80)});
 addEventListener('keyboardWillHide',()=>setTimeout(hold,50));
 try{visualViewport.addEventListener('resize',set)}catch(e){}addEventListener('wakhanKeyboardFrame',()=>setTimeout(set,0));
 addEventListener('keyboardWillShow',e=>{cap=+(e&&e.keyboardHeight)||0;set()});addEventListener('keyboardWillHide',()=>{cap=0;set()})})();
/* the host moves on by hand: the next video in the queue, or a chosen one (moved to the front, then started) */
async function skipTo(id){const k=K();if(!k)return;const c=k.cs();if(!c||!c.vid){note(t6('offline'),'x');return}
 try{if(id){const j=await qPost({action:'move',id,to:0});if(!j)return}
  const j=await WakhanSalonMusic.advance('next');if(j&&j.ok){try{cinSet(j)}catch(_){}hap();loadQ(true)}else{note(t6('offline'),'x');loadQ(true)}}catch(e){note(t6('offline'),'x')}}
function queuePage(){const k=K();if(!k)return;const w=document.createElement('div');w.className='slr-pg s6-qp';w.dir=RTL()?'rtl':'ltr';
 w.innerHTML=`<div class="r-pgh"><button class="r-pgb" data-q="back" aria-label="${esc(t6('back'))}">${S(IC.chev,2)}</button><div><b>${esc(t6('queue'))}</b><small><bdi>${esc(k.room().name||'')}</bdi></small></div></div>
  <div class="s6-qb"><div class="s6-now s6-skn"></div></div><div class="s6-qf"><button class="s6-go s6-add" data-q="add">${S(IC.plus,2.2)}<span>${esc(t6(isHost()?'addV':'suggestV'))}</span></button></div>`;
 document.body.appendChild(w);requestAnimationFrame(()=>w.classList.add('in'));
 let D=Q.d,drag=false;const body=w.querySelector('.s6-qb');
 const row=(x,i,host)=>`<div class="s6-it" data-id="${Number(x.id)}" style="--k:${Math.min(i,8)}"><em class="s6-n">${num(i+1)}</em><span class="s6-th"><img src="${esc(x.thumb||'')}" alt=""></span><span class="s6-tt"><b><bdi>${esc(x.title||'')}</bdi></b><small>${srcH(x.src)}</small></span>${host?`<button class="s6-ia s6-pn" data-q="pnow" aria-label="${esc(t6('qPlay'))}">${S(IC.play)}</button><button class="s6-ia" data-q="rm" aria-label="${esc(t6('remove'))}">${S(IC.trash,1.7)}</button><button class="s6-ia s6-grip" data-q="grip" aria-label="${esc(t6('move'))}">${S(IC.grip)}</button>`:''}</div>`;
 const prow=(x,i,host)=>{const mine=x.by&&Number(x.by.id)===k.me();return `<div class="s6-it s6-pi" data-id="${Number(x.id)}" style="--k:${Math.min(i,8)}"><span class="s6-th"><img src="${esc(x.thumb||'')}" alt=""></span><span class="s6-tt"><b><bdi>${esc(x.title||'')}</bdi></b><small class="s6-by">${x.by?k.ava(x.by):''}<span>${esc(t6('from',{n:(x.by&&x.by.name)||''}))}</span></small></span>
  ${host?`<button class="s6-ia s6-ok" data-q="ok" aria-label="${esc(t6('approve'))}">${S(IC.check,2.4)}</button><button class="s6-ia s6-no" data-q="no" aria-label="${esc(t6('reject'))}">${S(IC.x,2)}</button>`:mine?`<small class="s6-wt">${esc(t6('waiting'))}</small>`:''}</div>`};
 const time=()=>{let t=0,d=0;try{t=YTP.getCurrentTime();d=YTP.getDuration()}catch(e){}if(!d&&D&&D.now){t=D.now.t||0;d=D.now.d||0}return [t,d]};
 const tick=()=>{const n=w.querySelector('.s6-now');if(!n||!D||!D.now)return;const [t,d]=time();const a=n.querySelector('.s6-tm');if(a)a.textContent=mmss(t)+' / '+mmss(d);const p=n.querySelector('.s6-pr i');if(p)p.style.width=(d?Math.min(100,t/d*100):0)+'%'};
 const draw=()=>{if(!D||drag)return;const host=isHost();const nx=D.next||[],pd=D.pending||[];
  body.innerHTML=(D.now?`<div class="s6-now"><img src="${esc(D.now.thumb||'')}" alt=""><i class="s6-shd"></i><span class="s6-live"><i></i>${esc(t6('nowPlaying'))}</span>
    <div class="s6-nt"><b><bdi>${esc(D.now.title||'')}</bdi></b><small>${srcH(D.now.src)}</small></div>${host&&nx.length?`<button class="s6-skip" data-q="skip" aria-label="${esc(t6('qNext'))}">${S(IC.skip)}</button>`:''}<div class="s6-nb"><span class="s6-tm"></span><span class="s6-pr"><i></i></span></div></div>`:`<p class="s6-e s6-e2">${S(IC.film,1.6)}<span>${esc(t6('nothing'))}</span></p>`)
   +`<div class="s6-h"><b>${esc(t6('next'))}</b>${nx.length?`<small>${esc(t6('videos',{n:num(nx.length)}))}</small>`:''}</div>`
   +(nx.length?`<div class="s6-list" data-l="next">${nx.map((x,i)=>row(x,i,host)).join('')}</div>`:`<p class="s6-e">${S(IC.list,1.7)}<span>${esc(t6('empty'))}</span></p>`)
   +(pd.length?`<div class="s6-h"><b>${esc(t6('sugg'))}</b></div><div class="s6-list s6-pl2">${pd.map((x,i)=>prow(x,i,host)).join('')}</div>`:'');
  tick()};
 const sub=d=>{D=d;if(w.isConnected)draw()};Q.subs.add(sub);draw();loadQ(true);
 const iv=setInterval(()=>{if(!w.isConnected)return clearInterval(iv);tick()},1000);const pv=setInterval(()=>{if(!w.isConnected)return clearInterval(pv);if(!drag)loadQ(true)},4000);
 const close=()=>{Q.subs.delete(sub);clearInterval(iv);clearInterval(pv);w.classList.remove('in');w.classList.add('out');setTimeout(()=>w.remove(),260)};
 const gone=(el,fn)=>{el.classList.add('s6-gone');setTimeout(fn,260)};
 w.addEventListener('click',e=>{const b=e.target.closest('[data-q]');if(!b||b.disabled)return;const a=b.dataset.q;if(a==='grip')return;hap();
  if(a==='back')return close();if(a==='add')return pick();
  if(a==='skip'){b.disabled=true;skipTo(null).finally(()=>{b.disabled=false});return}
  const it=b.closest('.s6-it');const id=it&&+it.dataset.id;if(!id)return;b.disabled=true;
  if(a==='pnow'){skipTo(id).finally(()=>{b.disabled=false});return}
  if(a==='rm')return gone(it,()=>{D.next=(D.next||[]).filter(x=>x.id!==id);draw();qPost({action:'remove',id})});
  if(a==='no')return gone(it,()=>{D.pending=(D.pending||[]).filter(x=>x.id!==id);draw();qPost({action:'reject',id})});
  if(a==='ok')return gone(it,()=>{const x=(D.pending||[]).find(z=>z.id===id);D.pending=(D.pending||[]).filter(z=>z.id!==id);if(x)(D.next=D.next||[]).push(x);draw();const nr=w.querySelector(`.s6-list[data-l=next] .s6-it[data-id="${id}"]`);if(nr)nr.classList.add('s6-new');qPost({action:'approve',id})})});
 /* drag to reorder: hold the grip, slide up or down, let go */
 w.addEventListener('pointerdown',e=>{const h=e.target.closest('.s6-grip');if(!h)return;e.preventDefault();const it=h.closest('.s6-it'),list=it.parentNode,rows=[...list.children],i0=rows.indexOf(it);
  const H=it.getBoundingClientRect().height+parseFloat(getComputedStyle(list).rowGap||0),y0=e.clientY;let to=i0;drag=true;it.classList.add('s6-drag');try{h.setPointerCapture(e.pointerId)}catch(_){}
  const mv=ev=>{const dy=ev.clientY-y0;it.style.transform=`translateY(${dy}px) scale(1.02)`;to=Math.max(0,Math.min(rows.length-1,i0+Math.round(dy/H)));
   rows.forEach((r,j)=>{if(r===it)return;const s=i0<to&&j>i0&&j<=to?-H:i0>to&&j<i0&&j>=to?H:0;r.style.transform=s?`translateY(${s}px)`:''})};
  const up=()=>{h.removeEventListener('pointermove',mv);h.removeEventListener('pointerup',up);h.removeEventListener('pointercancel',up);drag=false;rows.forEach(r=>r.style.transform='');it.classList.remove('s6-drag');
   if(to!==i0){hap();const x=D.next.splice(i0,1)[0];D.next.splice(to,0,x);draw();qPost({action:'move',id:x.id,to})}};
  h.addEventListener('pointermove',mv);h.addEventListener('pointerup',up);h.addEventListener('pointercancel',up)})}

