/* bottom sheets with a text field (salon name, link, report…) rise above the iPhone keyboard; the app reports the keyboard itself */
(()=>{let cap=null;const set=()=>{const a=document.activeElement;const on=!!(a&&a.matches&&a.matches('input:not([type=range]):not([type=file]),textarea')&&a.closest('.s6-sh'));let kb=0;
