 document.documentElement.style.setProperty('--skb',kb+'px');document.documentElement.classList.toggle('s6-kbon',kb>0)};
 /* iPhone scrolls the whole app up to show the field; the sheet already rises by itself, so the app is held in place and put back
    exactly where it was when the keyboard closes (otherwise the next pages open under the clock) */
 let keep=null;const field=t=>t&&t.matches&&t.matches('input:not([type=range]):not([type=file]),textarea')&&t.closest('.s6-sh,.slr-pg,.s8-cr');
 const hold=()=>{if(keep==null)return;try{if(Math.abs(scrollY-keep)>1||(window.visualViewport&&visualViewport.offsetTop>0))window.scrollTo(0,keep)}catch(e){}};
 addEventListener('focusin',e=>{if(field(e.target)){if(keep==null)keep=scrollY;[60,250,500].forEach(t=>setTimeout(hold,t))}set();setTimeout(set,120);setTimeout(set,450)});
 addEventListener('focusout',e=>{setTimeout(()=>{set();if(keep!=null&&!field(document.activeElement)){hold();setTimeout(()=>{hold();keep=null},350)}},80)});
 addEventListener('keyboardWillHide',()=>setTimeout(hold,50));
 try{visualViewport.addEventListener('resize',set)}catch(e){}addEventListener('wakhanKeyboardFrame',()=>setTimeout(set,0));
 addEventListener('keyboardWillShow',e=>{cap=+(e&&e.keyboardHeight)||0;set()});addEventListener('keyboardWillHide',()=>{cap=0;set()})})();
