})();


/* Shared salon music protocol. Provider players stay in place across repeats. */
(()=>{'use strict';
if(window.WakhanSalonMusic)return;
const base='/api/media/salon/';
const room=()=>typeof CID==='undefined'?'':String(CID||'');
const state=()=>typeof CS==='undefined'?null:CS;
const identity=(code,s)=>[code,s&&s.vid,s&&s.music_generation,s&&s.timeline_revision].join('|');
const pending=new Map(),completed=new Set();
const item=v=>({src:v.src==='sc'?'soundcloud':v.src==='yt'?'youtube':v.src,ref:v.ref||v.url||v.id,
 title:v.title||'',ch:v.ch||'',thumb:v.thumb||'',dur:Number(v.dur)||0,music:true});
async function request(path,body){const j=await api(base+path,body);if(!j||!j.ok)throw Error(j&&j.err||'offline');return j}
function accept(j,code){if(code!==room()||!j)return false;const s=state();
 if(s&&s._cid===code&&Number.isFinite(Number(s.ver))&&Number(j.ver)<Number(s.ver))return false;
 j._cid=code;cinSet(j);return true}
async function play(v){const code=room(),j=await request('play',{code,item:item(v)});accept(j.state,code);return j}
async function advance(reason='next',player,vid){const s=state(),code=room();if(!s||!s.vid||!code)return null;
 if(vid&&vid!==s.vid)return null;
 if(!s.music_generation)throw Error('music_server_update_required');
 const key=identity(code,s);
 if(pending.has(key))return pending.get(key);
 if(reason==='end'&&completed.has(key))return null;
 const duration=Number(player?.getDuration?.()??player?.duration??s.music_duration);
 const task=(async()=>{const j=await request('advance',{code,vid:s.vid,generation:s.music_generation,
  revision:s.timeline_revision||0,reason,duration:Number.isFinite(duration)?duration:0});
  if(reason==='end'&&!j.ignored){completed.add(key);if(completed.size>100)completed.delete(completed.values().next().value)}
  accept(j.state,code);return {ok:true,...j.state};})();
 pending.set(key,task);
 try{return await task}finally{if(pending.get(key)===task)pending.delete(key)}
}
function finishing(){return pending.has(identity(room(),state()))}
/* Every phone may report a real end; the server accepts exactly one for that generation.
   Repeated callbacks and late polling replies cannot restart an already-started cycle. */
wmcFinishMedia=async function(player,vid=state()?.vid){const s=state();
 if(!s?.playing||s.mine<0||!vid||s.vid!==vid||!room())return null;
