const previousSet=cinSet;
const set=function(j){const s=state(),code=room();if(j?._cid&&String(j._cid)!==code)return;
 if(s?._cid===code&&j?.ok&&Number.isFinite(Number(j.ver))&&Number(j.ver)<Number(s.ver))return;
