 const before=state(),stream=String(path||'').startsWith('/api/stream?'),snapshot=before&&identity(room(),before),streamRoom=room();
 const j=await previousApi.apply(this,arguments);if(code&&j&&j.ok)j._cid=code;
 // Only a definitive server answer can skip a SoundCloud item. A phone's own
 // network failure, auth error, or a still-pending stream must never skip for everyone.
 if(stream&&j&&!j.ok&&!j.pending&&['fail','unplayable','not_found','source_unavailable','removed'].includes(j.err)){
  setTimeout(()=>{const current=state();if(streamRoom!==room()||snapshot!==identity(room(),current)||current?.media?.kind!=='soundcloud'||!current.can)return;
   try{window.SLR3?.k?.note('این آهنگ پخش نشد','x')}catch(_){}advance('unplayable').catch(()=>{})},0)}
 return j};
api=apiWithRoom;window.api=apiWithRoom;
const previousApply=cinApply;
cinApply=function(){if(finishing())return;return previousApply.apply(this,arguments)};
window.WakhanSalonMusic={search:q=>request('search?q='+encodeURIComponent(q)),play,advance,item,
 add:v=>request('queue',{code:room(),action:'add',item:item(v)}),finishing};
})();

